<!-- Pure Laravel Interactive Script -->
<script>
document.addEventListener('DOMContentLoaded', function() {
    var menuToggle = document.querySelector('.menu-toggle');
    var drawerCloseBtn = document.querySelector('.drawer-close-btn');
    var mobileDrawer = document.querySelector('#mobile-nav');
    var mobileBackdrop = document.querySelector('.mobile-drawer-backdrop');

    function openDrawer() {
        if (mobileDrawer) mobileDrawer.classList.add('is-open');
        if (mobileBackdrop) mobileBackdrop.classList.add('is-open');
        if (menuToggle) menuToggle.setAttribute('aria-expanded', 'true');
    }

    function closeDrawer() {
        if (mobileDrawer) mobileDrawer.classList.remove('is-open');
        if (mobileBackdrop) mobileBackdrop.classList.remove('is-open');
        if (menuToggle) menuToggle.setAttribute('aria-expanded', 'false');
    }

    if (menuToggle) menuToggle.addEventListener('click', openDrawer);
    if (drawerCloseBtn) drawerCloseBtn.addEventListener('click', closeDrawer);
    if (mobileBackdrop) mobileBackdrop.addEventListener('click', closeDrawer);

    var enquiryDialog = document.querySelector('dialog.enquiry');
    var enquiryTriggers = document.querySelectorAll('[data-enquiry]');
    var dialogCloseBtn = document.querySelector('.dialog-close');

    if (enquiryTriggers.length && enquiryDialog) {
        enquiryTriggers.forEach(function(btn) {
            btn.addEventListener('click', function(e) {
                e.preventDefault();
                if (typeof enquiryDialog.showModal === 'function') enquiryDialog.showModal();
                else enquiryDialog.classList.add('is-open');
            });
        });
    }

    if (dialogCloseBtn && enquiryDialog) {
        dialogCloseBtn.addEventListener('click', function() {
            if (typeof enquiryDialog.close === 'function') enquiryDialog.close();
            else enquiryDialog.classList.remove('is-open');
        });
    }
});
</script>
